package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService provides methods for interacting with users
type UserService struct {
	users  map[string]User
	mutex  sync.RWMutex
}

// NewUserService creates and returns a new UserService
func NewUserService() *UserService {
	return &UserService{
		users: make(map[string]User),
	}
}

// GetAllUsers returns a list of all users
func (s *UserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and adds it to the system
func (s *UserService) CreateUser(user User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	user.ID = uuid.New().String()
	s.users[user.ID] = user
	return user, nil
}

// GetUserByID retrieves a user by their ID
func (s *UserService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"

	"legacy_refactor/internal/service"
)

// UserHandler handles HTTP requests for users
type UserHandler struct {
	service *service.UserService
}

// NewUserHandler creates and returns a new UserHandler
func NewUserHandler(s *service.UserService) *UserHandler {
	return &UserHandler{service: s}
}

// HandleUsers manages requests to /users
func (h *UserHandler) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.GetAllUsers(w, r)
	case http.MethodPost:
		h.CreateUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// HandleUserByID manages requests to /users/{id}
func (h *UserHandler) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/users/")

	switch r.Method {
	case http.MethodGet:
		h.GetUserByID(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetAllUsers handles GET requests for all users
func (h *UserHandler) GetAllUsers(w http.ResponseWriter, r *http.Request) {
	users := h.service.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUser handles POST requests to create a new user
func (h *UserHandler) CreateUser(w http.ResponseWriter, r *http.Request) {
	var user service.User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.service.CreateUser(user)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUserByID handles GET requests for a user by ID
func (h *UserHandler) GetUserByID(w http.ResponseWriter, r *http.Request, id string) {
	user, ok := h.service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

package main

import (
	"log"
	"net/http"

	"legacy_refactor/internal/api"
	"legacy_refactor/internal/service"
)

func main() {
	svc := service.NewUserService()
	handler := api.NewUserHandler(svc)

	http.HandleFunc("/users", handler.HandleUsers)
	http.HandleFunc("/users/", handler.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service_test

import (
	"legacy_refactor/internal/service"
	testing"
)

func TestUserService_CreateUser(t *testing.T) {
	svc := service.NewUserService()

	user := service.User{Name: "John Doe", Email: "john@example.com"}
	createdUser, err := svc.CreateUser(user)
	if err != nil {
		t.Fatalf("CreateUser failed: %v", err)
	}

	if createdUser.ID == "" {
		t.Error("Expected user ID to be generated, got empty string")
	}
	if createdUser.Name != user.Name {
		t.Errorf("Expected user name %s, got %s", user.Name, createdUser.Name)
	}

	// Try to retrieve the user
	retrievedUser, ok := svc.GetUserByID(createdUser.ID)
	if !ok {
		t.Error("Expected to retrieve created user, but got not found")
	}
	if retrievedUser.ID != createdUser.ID {
		t.Errorf("Expected retrieved user ID %s, got %s", createdUser.ID, retrievedUser.ID)
	}
}

func TestUserService_GetAllUsers(t *testing.T) {
	svc := service.NewUserService()

	user1 := service.User{Name: "John Doe", Email: "john@example.com"}
	user2 := service.User{Name: "Jane Doe", Email: "jane@example.com"}

	svc.CreateUser(user1)
	svc.CreateUser(user2)

	users := svc.GetAllUsers()
	if len(users) != 2 {
		t.Errorf("Expected 2 users, got %d", len(users))
	}

	foundJohn := false
	foundJane := false
	for _, u := range users {
		if u.Name == "John Doe" {
			foundJohn = true
		}
		if u.Name == "Jane Doe" {
			foundJane = true
		}
	}

	if !foundJohn || !foundJane {
		t.Error("Expected to find both John and Jane Doe in the list")
	}
}

